export function DoubleSidebarLayout({ pageHeaderContent, pageLeftSidebarContent, mainContainerContent }) {
  return (
    <Page>
      <PageHeader>{pageHeaderContent}</PageHeader>
      <PageBody>
        <PageLeftSidebar>{pageLeftSidebarContent}</PageLeftSidebar>
        <Main><MainContent><MainBody><MainContainer>{mainContainerContent}</MainContainer></MainBody></MainContent></Main>
      </PageBody>
    </Page>
  )
}

export function SettingsLayout() {
  const entries = navOf(settingsRoutes)          // the projection: title, path, to
  const current = useCurrentPath()               // the router's current route
  return (
    <DoubleSidebarLayout
      pageHeaderContent={<TitleHeader icon="settings" title="Settings" />}
      pageLeftSidebarContent={<SettingsNav entries={entries} current={current} />}
      mainContainerContent={<Outlet />}
    />
  )
}

const ICONS = { profile: "user", security: "lock", account: "mail" }

export function SettingsNav({ entries, current }: { entries: NavEntry[]; current: string }) {
  return (
    <nav element="control-group--sidebar">
      {entries.map((e) => (
        <SidebarItem key={e.path} to={e.to} icon={ICONS[e.path]} selected={e.to === current}>{e.title}</SidebarItem>
      ))}
    </nav>
  )
}
